#!/usr/bin/env python3
import sys


def solve(K: int):
    s = 0
    for i in range(1, K + 1):
        for j in range(1, K + 1):
            g1 = gcd(i, j)
            for k in range(1, K + 1):
                g2 = gcd(g1, k)
                s += g2
    print(s)
    return


def gcd(a, b):
    while b:
        a, b = b, a % b
    return a
